package com.madar.files;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
/** Loopback only, per-activity random bearer path, bounded connections, explicit file resolver. */
final class LocalMediaServer implements AutoCloseable {
 interface Resolver{Media resolve(String route,String name)throws Exception;}
 static final class Media{final File file;final String mime;Media(File f,String m){file=f;mime=m!=null&&m.matches("[A-Za-z0-9.+-]+/[A-Za-z0-9.+-]+")?m:"application/octet-stream";}}
 private final ServerSocket server;private final String token=UUID.randomUUID().toString().replace("-","");private final Resolver resolver;private final Set<Socket> clients=ConcurrentHashMap.newKeySet();private volatile boolean closed;
 private final ThreadPoolExecutor workers=new ThreadPoolExecutor(1,4,30,TimeUnit.SECONDS,new ArrayBlockingQueue<>(8),r->{Thread t=new Thread(r,"madar-media-stream");t.setDaemon(true);return t;});
 LocalMediaServer(Resolver resolver)throws IOException{this.resolver=resolver;server=new ServerSocket();server.bind(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),0),8);Thread thread=new Thread(()->{while(!closed)try{Socket socket=server.accept();socket.setSoTimeout(5000);clients.add(socket);try{workers.execute(()->serve(socket));}catch(RejectedExecutionException e){clients.remove(socket);socket.close();}}catch(IOException e){if(closed)return;}},"madar-media-listener");thread.setDaemon(true);thread.start();}
 String base(){return "http://127.0.0.1:"+server.getLocalPort()+"/"+token;}
 boolean owns(android.net.Uri uri){return "http".equals(uri.getScheme())&&"127.0.0.1".equals(uri.getHost())&&uri.getPort()==server.getLocalPort()&&uri.getPath()!=null&&uri.getPath().startsWith("/"+token+"/");}
 private String line(InputStream input)throws IOException{ByteArrayOutputStream bytes=new ByteArrayOutputStream();for(int i=0;i<4096;i++){int ch=input.read();if(ch<0)return bytes.size()==0?null:bytes.toString("US-ASCII");if(ch=='\n')return bytes.toString("US-ASCII").replace("\r","");bytes.write(ch);}throw new IOException("Header too long");}
 private void header(OutputStream out,int status,long length,String mime,String range)throws IOException{String reason=status==200?"OK":status==206?"Partial Content":status==403?"Forbidden":status==404?"Not Found":status==416?"Range Not Satisfiable":"Bad Request";String text="HTTP/1.1 "+status+" "+reason+"\r\nConnection: close\r\nCache-Control: no-store\r\nAccept-Ranges: bytes\r\nAccess-Control-Allow-Origin: https://madar.local\r\nAccess-Control-Allow-Methods: GET, HEAD, OPTIONS\r\nAccess-Control-Allow-Headers: Range\r\nCross-Origin-Resource-Policy: cross-origin\r\nContent-Type: "+mime+"\r\nContent-Length: "+length+"\r\n"+(range==null?"":"Content-Range: "+range+"\r\n")+"\r\n";out.write(text.getBytes(StandardCharsets.US_ASCII));}
 private void serve(Socket socket){try(Socket connection=socket;InputStream in=new BufferedInputStream(connection.getInputStream());OutputStream out=new BufferedOutputStream(connection.getOutputStream())){String first=line(in);if(first==null)return;String[] parts=first.split(" ");if(parts.length!=3){header(out,400,0,"text/plain",null);return;}Map<String,String> headers=new HashMap<>();for(int i=0;i<40;i++){String value=line(in);if(value==null||value.isEmpty())break;int colon=value.indexOf(':');if(colon>0)headers.put(value.substring(0,colon).toLowerCase(Locale.ROOT),value.substring(colon+1).trim());}
  android.net.Uri uri=android.net.Uri.parse("http://localhost"+parts[1]);String path=uri.getPath(),prefix="/"+token+"/";if(path==null||!path.startsWith(prefix)){header(out,403,0,"text/plain",null);return;}if(parts[0].equals("OPTIONS")){header(out,200,0,"text/plain",null);return;}if(!parts[0].equals("GET")&&!parts[0].equals("HEAD")){header(out,400,0,"text/plain",null);return;}
  Media media;try{media=resolver.resolve(path.substring(prefix.length()),uri.getQueryParameter("name"));}catch(Exception e){media=null;}if(media==null||media.file==null||!media.file.isFile()){header(out,404,0,"text/plain",null);return;}
  long size=media.file.length(),start=0,end=size-1;boolean partial=false;String range=headers.get("range");if(range!=null){if(!range.matches("bytes=[0-9]*-[0-9]*")){header(out,416,0,"text/plain","bytes */"+size);return;}String[] values=range.substring(6).split("-",-1);try{if(values[0].isEmpty()){long suffix=Long.parseLong(values[1]);if(suffix<1)throw new NumberFormatException();start=Math.max(0,size-suffix);}else{start=Long.parseLong(values[0]);if(!values[1].isEmpty())end=Math.min(end,Long.parseLong(values[1]));}partial=true;}catch(NumberFormatException e){header(out,416,0,"text/plain","bytes */"+size);return;}}
  if(start<0||start>=size||end<start){header(out,416,0,"text/plain","bytes */"+size);return;}long count=end-start+1;header(out,partial?206:200,count,media.mime,partial?"bytes "+start+"-"+end+"/"+size:null);if(parts[0].equals("HEAD"))return;try(RandomAccessFile file=new RandomAccessFile(media.file,"r")){file.seek(start);byte[] buffer=new byte[65536];while(count>0&&!closed){int n=file.read(buffer,0,(int)Math.min(count,buffer.length));if(n<0)break;out.write(buffer,0,n);count-=n;}}
 }catch(IOException ignored){}finally{clients.remove(socket);}}
 @Override public void close(){closed=true;try{server.close();}catch(IOException ignored){}for(Socket socket:clients)try{socket.close();}catch(IOException ignored){}clients.clear();workers.shutdownNow();}
}
